exec('import csv,os,yfinance as yf\nfrom datetime import datetime\nfrom zoneinfo import ZoneInfo\nf="virtual_portfolio.csv"; positions=list(csv.DictReader(open(f,encoding="utf-8"))) if os.path.exists(f) else []\nactive=set(x.strip() for x in open("stocks.txt",encoding="utf-8") if x.strip()); rows=[r for r in csv.DictReader(open("signals_history.csv",encoding="utf-8")) if r["ticker"] in active]; latest={}\nfor r in rows:\n if r["ticker"] not in latest or r["date"]>latest[r["ticker"]]["date"]: latest[r["ticker"]]=r\nused={(p["ticker"],p.get("signal_date",p.get("entry_date",""))) for p in positions}; tracked={p["ticker"] for p in positions if p.get("status") in ("OPEN","PENDING")}; slots=max(0,5-len(tracked))\nfor t,r in latest.items():\n if slots>0 and r["signal"]=="ACHAT" and t not in tracked and (t,r["date"]) not in used:\n  currency="EUR" if t.endswith((".PA",".AS")) else "USD"; positions.append({"ticker":t,"signal_date":r["date"],"signal_price":r["price"],"entry_date":"","entry_price":"","entry_type":"OUVERTURE_J","currency":currency,"eurusd_entry":"","quantity":"","invested_eur":"1000","target_price":"","stop_price":"","status":"PENDING","last_price":"","current_value_eur":"1000","pnl_eur":"0","pnl_pct":"0","exit_date":"","exit_price":"","exit_reason":""}); tracked.add(t); slots-=1; print("CANDIDAT PENDING :",t,"| Signal J-1 :",r["date"])\nfx=yf.download("EURUSD=X",period="3mo",progress=False,auto_adjust=True)["Close"].squeeze().dropna()\ndef fx_at(date):\n q=fx[fx.index.strftime("%Y-%m-%d")<=date]; return float(q.iloc[-1]) if len(q)>0 else float(fx.iloc[-1])\ndef market_data(t):\n tz="Europe/Paris" if t.endswith((".PA",".AS")) else "America/New_York"; now=datetime.now(ZoneInfo(tz)); closed=now.hour>17 or (now.hour==17 and now.minute>=40) if tz=="Europe/Paris" else now.hour>16 or (now.hour==16 and now.minute>=10); d=yf.download(t,period="3mo",progress=False,auto_adjust=True); mask=[x.date()<=now.date() if closed else x.date()<now.date() for x in d.index]; return d.loc[mask]\nfor p in positions:\n if p.get("status")=="PENDING":\n  d=yf.download(p["ticker"],period="5d",interval="5m",progress=False,auto_adjust=True,prepost=False); o=d["Open"].squeeze().dropna(); o=o[o.index.strftime("%Y-%m-%d")>p["signal_date"]]\n  if len(o)==0: print("EN ATTENTE OUVERTURE JOUR J :",p["ticker"]); continue\n  entry_date=o.index[0].strftime("%Y-%m-%d"); entry=float(o.iloc[0]); rate=fx_at(entry_date); qty=1000/entry if p["currency"]=="EUR" else 1000*rate/entry; p["entry_date"]=entry_date; p["entry_price"]=round(entry,4); p["eurusd_entry"]=1 if p["currency"]=="EUR" else round(rate,6); p["quantity"]=round(qty,6); p["target_price"]=round(entry*1.03,4); p["stop_price"]=round(entry*0.98,4); p["status"]="OPEN"; p["last_price"]=round(entry,4); p["current_value_eur"]="1000"; p["pnl_eur"]="0"; p["pnl_pct"]="0"; print("ACHAT JOUR J :",p["ticker"],"|",entry_date,"|",round(entry,2),p["currency"],"| Objectif",round(entry*1.03,2),"| Stop",round(entry*0.98,2))\nfor p in positions:\n if p.get("status")!="OPEN": continue\n d=yf.download(p["ticker"],period="1mo",interval="5m",progress=False,auto_adjust=True,prepost=False); after=d[d.index.strftime("%Y-%m-%d")>=p["entry_date"]] if p.get("entry_type")=="OUVERTURE_J" else d[d.index.strftime("%Y-%m-%d")>p["entry_date"]]; exit_found=False\n for day,row in after.iterrows():\n  low=float(row["Low"].iloc[0] if hasattr(row["Low"],"iloc") else row["Low"]); high=float(row["High"].iloc[0] if hasattr(row["High"],"iloc") else row["High"])\n  if low<=float(p["stop_price"]): p["status"]="CLOSED"; p["exit_date"]=day.strftime("%Y-%m-%d"); p["exit_price"]=p["stop_price"]; p["exit_reason"]="STOP -2%"; p["trigger_time"]=str(day); p["trigger_low"]=round(low,4); p["trigger_high"]=round(high,4); p["stop_level"]=p["stop_price"]; p["execution_price"]=p["stop_price"]; exit_found=True; break\n  if high>=float(p["target_price"]): p["status"]="CLOSED"; p["exit_date"]=day.strftime("%Y-%m-%d"); p["exit_price"]=p["target_price"]; p["exit_reason"]="OBJECTIF +3%"; exit_found=True; break\n current=float(p["exit_price"]) if exit_found else float(d["Close"].squeeze().dropna().iloc[-1]); value_date=p["exit_date"] if exit_found else d.index[-1].strftime("%Y-%m-%d"); rate=fx_at(value_date); value=float(p["quantity"])*current if p["currency"]=="EUR" else float(p["quantity"])*current/rate; p["last_price"]=round(current,4); p["current_value_eur"]=round(value,2); p["pnl_eur"]=round(value-float(p["invested_eur"]),2); p["pnl_pct"]=round((value/float(p["invested_eur"])-1)*100,2); print(p["ticker"],"|",p["status"],"| Valeur",p["current_value_eur"],"EUR | Resultat",p["pnl_eur"],"EUR |",p["pnl_pct"],"%",("| "+p["exit_reason"] if exit_found else ""))\nfields=["ticker","signal_date","signal_price","entry_date","entry_price","entry_type","currency","eurusd_entry","quantity","invested_eur","target_price","stop_price","status","last_price","current_value_eur","pnl_eur","pnl_pct","exit_date","exit_price","exit_reason"]\nwith open(f,"w",newline="",encoding="utf-8") as q:\n w=csv.DictWriter(q,fieldnames=fields,extrasaction="ignore"); w.writeheader(); w.writerows(positions)\nprint("Portefeuille virtuel miss a jour :",f)')
